package com.bank.news;

import java.util.List;
import java.util.logging.*;

public class NewsRoutingDemo {

    private static final Logger log = Logger.getLogger(NewsRoutingDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        // Build the four events, each tagged with category/country/city.
        List<NewsEvent> events = List.of(
            new NewsEvent("ps/news/SPORT/BR/SaoPaulo",    "Sao Paulo stadium sponsorship signed"),
            new NewsEvent("ps/news/POLITICS/BR/Brasilia", "Brazil central bank policy update"),
            new NewsEvent("ps/news/SPORT/IN/Mumbai",      "Mumbai cricket league media deal"),
            new NewsEvent("ps/news/MARKETS/US/NewYork",   "US equity index rebalance")
        );

        // ---------- SOLACE STYLE: broker routes by pattern ----------
        log.info("=== SOLACE hierarchical routing (broker filters) ===");
        SolaceStyleBroker broker = new SolaceStyleBroker();
        // Priya: every Brazil event, any category, any city.
        broker.subscribe("priya-brazil-desk", "ps/news/*/BR/>");
        // Rajesh: every sport event, any country, any city.
        broker.subscribe("rajesh-sports-desk", "ps/news/SPORT/>");
        events.forEach(broker::publish);

        // ---------- KAFKA STYLE: broker dumb, consumer filters ----------
        log.info("=== KAFKA flat topic (consumer filters) ===");
        KafkaStyleTopic topic = new KafkaStyleTopic("news.events");
        events.forEach(topic::append);              // every event stored, no routing
        topic.consumeFiltered("priya-brazil-desk",
            e -> e.level(2).equals("BR"));          // consumer code does the matching
        topic.consumeFiltered("rajesh-sports-desk",
            e -> e.level(1).equals("SPORT"));
    }
}

// ─── Would be in model/NewsEvent.java ───
class NewsEvent {
    private final String topic;     // e.g. ps/news/SPORT/BR/SaoPaulo
    private final String payload;
    NewsEvent(String topic, String payload) { this.topic = topic; this.payload = payload; }
    String topic()   { return topic; }
    String payload() { return payload; }
    // level(0)=news-root ... we index from after "ps/news/"
    String level(int idx) {
        String[] parts = topic.split("/");          // [ps, news, SPORT, BR, SaoPaulo]
        int real = idx + 2;
        return real < parts.length ? parts[real] : "";
    }
}

// ─── Would be in solace/SolaceStyleBroker.java ───
class SolaceStyleBroker {
    private static final Logger log = Logger.getLogger(SolaceStyleBroker.class.getName());
    private final java.util.Map<String, String> subscriptions = new java.util.LinkedHashMap<>();

    void subscribe(String name, String pattern) {
        subscriptions.put(name, pattern);
        log.info(() -> "subscribe " + name + " -> " + pattern);
    }

    // Broker evaluates every subscription against the published topic.
    void publish(NewsEvent event) {
        for (var entry : subscriptions.entrySet()) {
            if (matches(entry.getValue(), event.topic())) {
                log.info(() -> "DELIVER to " + entry.getKey()
                        + " : " + event.topic() + " [" + event.payload() + "]");
            }
        }
    }

    // Implements Solace '*' (one level) and '>' (one-or-more trailing levels).
    boolean matches(String pattern, String topic) {
        String[] p = pattern.split("/");
        String[] t = topic.split("/");
        int i = 0;
        for (; i < p.length; i++) {
            if (p[i].equals(">")) return true;                 // matches rest
            if (i >= t.length) return false;                   // pattern longer than topic
            if (p[i].equals("*")) continue;                    // matches exactly one level
            if (!p[i].equals(t[i])) return false;              // literal mismatch
        }
        return i == t.length;                                   // no '>' => lengths must match
    }
}

// ─── Would be in kafka/KafkaStyleTopic.java ───
class KafkaStyleTopic {
    private static final Logger log = Logger.getLogger(KafkaStyleTopic.class.getName());
    private final String name;
    private final java.util.List<NewsEvent> logStore = new java.util.ArrayList<>();
    KafkaStyleTopic(String name) { this.name = name; }

    void append(NewsEvent e) {                                  // no routing, just append
        logStore.add(e);
        log.fine(() -> "append to " + name + " : " + e.topic());
    }

    // The consumer reads EVERYTHING and filters in application code.
    void consumeFiltered(String consumer, java.util.function.Predicate<NewsEvent> keep) {
        for (NewsEvent e : logStore) {
            if (keep.test(e)) {
                log.info(() -> consumer + " KEEP   " + e.topic());
            } else {
                log.fine(() -> consumer + " DISCARD " + e.topic());
            }
        }
    }
}

